CREATE TABLE cms_contact_secrets (name TEXT PRIMARY KEY CHECK (name IN ('RESEND_API_KEY','CONTACT_TO','TURNSTILE_SITE_KEY','TURNSTILE_SECRET_KEY')), iv BLOB NOT NULL CHECK (length(iv) = 12), ciphertext BLOB NOT NULL CHECK (length(ciphertext) BETWEEN 17 AND 1040), updated_at TEXT NOT NULL, updated_by TEXT NOT NULL);
CREATE TABLE cms_sent_mail (id INTEGER PRIMARY KEY AUTOINCREMENT, resend_id TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK (kind IN ('test','custom')), recipients TEXT NOT NULL, subject TEXT NOT NULL, attachments INTEGER NOT NULL DEFAULT 0 CHECK (attachments BETWEEN 0 AND 10), created_at TEXT NOT NULL, scheduled_at TEXT, canceled_at TEXT, actor TEXT NOT NULL);
CREATE TABLE cms_mail_files (id TEXT PRIMARY KEY, object_key TEXT NOT NULL UNIQUE CHECK (object_key = 'mail-private/' || id), name TEXT NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL CHECK (bytes > 0 AND bytes <= 31457280), created_at TEXT NOT NULL, sent_at TEXT, expires_at TEXT NOT NULL);
CREATE INDEX cms_mail_files_expiry ON cms_mail_files(expires_at);
